  // ── 阵营说明 ──
  '钢铁与工厂的工业强国，信奉火力与装甲。': 'Индустриальная держава стали и заводов, которая верит в огневую мощь и броню.',  // FACTIONS.1.culture
  '履带车辆防御 +5%；陆上单位在兵工厂的修理费 −20%。': 'Защита гусеничной техники +5%; цена ремонта наземных юнитов на заводе −20%.',  // FACTIONS.1.trait
  '海洋与天空的联邦，重视技术与后勤。': 'Федерация моря и неба, которая ценит технологии и тыловое обеспечение.',  // FACTIONS.2.culture
  '航空单位和舰船视野 +1；航空单位在机场、舰船在港口的修理费 −20%。': 'Обзор воздушных юнитов и кораблей +1; цена ремонта воздушных юнитов на аэродроме и кораблей в порту −20%.',  // FACTIONS.2.trait
  '山林与雪原的游击之民，擅长地形与隐蔽。': 'Партизанский народ гор, лесов и снежных равнин, мастера местности и скрытности.',  // FACTIONS.3.culture
