  // ── 兵种说明 ──
  '造价低廉，可占领建筑，可进入山地与河流。': 'Стоит дёшево, может захватывать здания, может входить в горы и реки.',  // UNITS.inf.desc
  '装备火箭筒的步兵，可占领建筑，对坦克伤害较高，在山地、河流上的移动消耗为 1。': 'Боец с гранатомётом: может захватывать здания, наносит высокий урон танкам, затраты движения в горах и на реке равны 1.',  // UNITS.mech.desc
  '射程 2–4 的远程步兵，擅长攻击步兵类单位，也可攻击轻型车辆和直升机。在山地上射程 +1。移动后不可攻击。': 'Дальнобойный пехотный юнит с дальностью 2–4, эффективен против пехоты, может атаковать лёгкую технику и вертолёты. В горах дальность +1. После движения атаковать не может.',  // UNITS.snp.desc
  '射程 1–2，移动后仍可攻击。攻击时目标的地形防御减半，擅长攻击位于建筑、森林、山地的步兵类单位。攻击 2 格外的目标时不受反击。在山地上射程 +1。不可攻击航空单位和舰船，不可占领。': 'Дальность 1–2, может атаковать после движения. При атаке защита местности цели уменьшается вдвое; эффективен против пехоты в зданиях, лесу и горах. При атаке цели на расстоянии 2 клеток не получает контратаки. В горах дальность +1. Не может атаковать воздушные юниты и корабли, не может захватывать.',  // UNITS.grn.desc
  '射程 1，攻击时无视目标的地形防御，擅长攻击位于建筑、山地的步兵类单位。迷雾开启时，可发现周围 8 格森林、废墟中的隐蔽单位。不敌远程单位和车辆，不可攻击航空单位和舰船，不可占领。': 'Дальность 1, при атаке игнорирует защиту местности цели; эффективен против пехоты в зданиях и горах. Если туман включён, обнаруживает скрытые юниты в лесу и руинах в 8 клетках вокруг себя. Слаб против дальнобойных юнитов и техники, не может атаковать воздушные юниты и корабли, не может захватывать.',  // UNITS.flm.desc
  '无武装。相邻的己方步兵类单位每回合恢复 2 HP（无需支付资金）。多名医护兵的效果不叠加。': 'Без оружия. Ваша пехота на соседних клетках восстанавливает 2 HP за ход (без оплаты). Эффект нескольких санитаров не складывается.',  // UNITS.mdc.desc
  '乘坐摩托车的步兵，可占领建筑，移动力高，适合占领远处的建筑。不可进入山地。': 'Боец на мотоцикле: может захватывать здания, обладает высоким движением, подходит для захвата дальних зданий. Не может входить в горы.',  // UNITS.bik.desc
  '陆上单位中移动力最高，擅长攻击步兵类单位和无掩护的火炮，不敌坦克。': 'Самое высокое движение среди наземных юнитов; эффективна против пехоты и артиллерии без прикрытия, слаба против танков.',  // UNITS.rec.desc
  '陆上主力，造价较低，攻击与防御均衡。': 'Основа наземных сил: невысокая цена, сбалансированные атака и защита.',  // UNITS.tnk.desc
  '攻击与防御高于轻型坦克，造价适中。': 'Атака и защита выше, чем у лёгкого танка; цена умеренная.',  // UNITS.med.desc
  '陆上单位中攻击与防御最高，造价高，移动力低。': 'Самые высокие атака и защита среди наземных юнитов; высокая цена, низкое движение.',  // UNITS.hvy.desc
  '射程 2–3，可攻击舰船。移动后不可攻击，不可攻击相邻的敌方单位。': 'Дальность 2–3, может атаковать корабли. После движения атаковать не может, не может атаковать соседние вражеские юниты.',  // UNITS.art.desc
  '射程 3–5，射程长于自行火炮，擅长攻击重型车辆。移动后不可攻击。': 'Дальность 3–5, больше, чем у САУ; эффективна против тяжёлой техники. После движения атаковать не может.',  // UNITS.rkt.desc
  '射程 1，擅长攻击航空单位，对步兵类单位伤害也较高。': 'Дальность 1; эффективна против воздушных юнитов, наносит высокий урон и пехоте.',  // UNITS.aa.desc
  '无武装。相邻的己方车辆、航空单位、舰船每回合恢复 1 HP（无需支付资金）。': 'Без оружия. Ваша техника, воздушные юниты и корабли на соседних клетках восстанавливают 1 HP за ход (без оплаты).',  // UNITS.rep.desc
  '移动不受地形影响，擅长攻击陆上单位，不敌防空车。': 'Местность не влияет на движение; эффективен против наземных юнитов, слаб против ЗСУ.',  // UNITS.cop.desc
  '可攻击陆上单位和直升机，造价低于轰炸机。': 'Может атаковать наземные юниты и вертолёты; цена ниже, чем у бомбардировщика.',  // UNITS.atk.desc
  '对陆上单位和舰船伤害极高，不可攻击航空单位。': 'Крайне высокий урон по наземным юнитам и кораблям; не может атаковать воздушные юниты.',  // UNITS.bmb.desc
  '造价低廉的小型舰船，可攻击岸边的陆上单位，擅长攻击登陆艇。': 'Дешёвый малый корабль: может атаковать наземные юниты у берега, эффективен против десантных катеров.',  // UNITS.gbt.desc
  '兼具防空与反潜能力，擅长攻击潜艇和航空单位。': 'Сочетает противовоздушную и противолодочную оборону; эффективен против подлодок и воздушных юнитов.',  // UNITS.dst.desc
  '射程 2–6，可攻击陆上单位和舰船，伤害较高。移动后不可攻击。': 'Дальность 2–6, может атаковать наземные юниты и корабли, урон высокий. После движения атаковать не может.',  // UNITS.bsh.desc
  '无武装。可搭载 2 个陆上单位，靠岸后卸载。': 'Без оружия. Перевозит 2 наземных юнита и высаживает их у берега.',  // UNITS.lnd.desc

