  // ── 地形说明 ──
  '轮式车辆的移动消耗为 3。': 'Затраты движения колёсной техники равны 3.',  // TERRAIN.waste.note
  '陆上单位的移动消耗增加，轮式车辆不可进入。': 'Затраты движения наземных юнитов увеличены, колёсная техника входить не может.',  // TERRAIN.swamp.note
  '陆上单位与舰船不可通过，航空单位可飞越。': 'Наземные юниты и корабли пройти не могут, воздушные юниты перелетают.',  // TERRAIN.wall.note
  '每回合提供 100 资金。停留的己方陆上单位每回合恢复 2 HP（需支付资金）。': 'Даёт 100 средств за ход. Ваши наземные юниты, стоящие здесь, восстанавливают 2 HP за ход (за плату).',  // TERRAIN.city.note
  '每回合提供 100 资金。可生产陆上单位。停留的己方陆上单位每回合恢复 2 HP（需支付资金）。': 'Даёт 100 средств за ход. Производит наземные юниты. Ваши наземные юниты, стоящие здесь, восстанавливают 2 HP за ход (за плату).',  // TERRAIN.factory.note
  '每回合提供 100 资金。可生产航空单位。停留的己方航空单位与步兵类单位每回合恢复 2 HP（需支付资金）。': 'Даёт 100 средств за ход. Производит воздушные юниты. Ваши воздушные юниты и пехота, стоящие здесь, восстанавливают 2 HP за ход (за плату).',  // TERRAIN.airport.note
  '每回合提供 100 资金。可生产舰船。停留的己方舰船与步兵类单位每回合恢复 2 HP（需支付资金）。': 'Даёт 100 средств за ход. Производит корабли. Ваши корабли и пехота, стоящие здесь, восстанавливают 2 HP за ход (за плату).',  // TERRAIN.port.note
  '停留的己方步兵类单位每回合恢复 2 HP（需支付资金）。己方雷达塔 5 格范围内的己方单位攻击 +10%。多座雷达塔的效果不叠加。': 'Ваша пехота, стоящая здесь, восстанавливает 2 HP за ход (за плату). Ваши юниты в пределах 5 клеток от вашего радара получают атаку +10%. Эффект нескольких радаров не складывается.',  // TERRAIN.tower.note
  '停留的己方步兵类单位每回合恢复 4 HP，相邻四格内的己方步兵类单位每回合恢复 2 HP（需支付资金）。': 'Ваша пехота, стоящая здесь, восстанавливает 4 HP за ход, а ваша пехота на четырёх соседних клетках — 2 HP за ход (за плату).',  // TERRAIN.hospital.note
  '停留的己方步兵类单位每回合恢复 2 HP（需支付资金）。位于己方或中立碉堡的单位受到的反击伤害减半，其中远程单位（含投弹手）射程 +1。': 'Ваша пехота, стоящая здесь, восстанавливает 2 HP за ход (за плату). Юниты в вашем или нейтральном доте получают вдвое меньший урон от контратак, а дальнобойные юниты среди них (включая гренадеров) получают дальность +1.',  // TERRAIN.fort.note
  '可占领建筑的兵种（步兵、破甲兵、摩托兵）进入后可发射一次：指定一格为中心，2 格内所有单位各损失 3 HP（最低保留 1 HP）。': 'Юнит, способный захватывать здания (стрелок, гранатомётчик, мотоциклист), войдя сюда, может один раз запустить ракету: указывается центральная клетка, и все юниты в пределах 2 клеток от неё теряют по 3 HP (остаётся не менее 1 HP).',  // TERRAIN.silo.note

