  '全军攻击 +5%。': 'Атака всей армии +5%.',  // TECH.arm1.desc
  '车辆、舰船、航空单位防御 +10%。': 'Защита техники, кораблей и воздушных юнитов +10%.',  // TECH.arm2.desc
  '攻击时，目标相邻四格内每有一个其他己方单位，攻击 +5%，最多 +15%。': 'При атаке за каждый другой ваш юнит на четырёх клетках, соседних с целью, атака +5%, не более +15%.',  // TECH.arm3.desc
  '在建筑上修理时每回合额外恢复 1 HP，修理费 −30%。': 'При ремонте в зданиях юниты дополнительно восстанавливают 1 HP за ход, цена ремонта −30%.',  // TECH.log1.desc
  '所有单位造价 −8%。': 'Цена всех юнитов −8%.',  // TECH.log2.desc
  '回合开始时位于道路或桥梁的单位，本回合移动力 +1。': 'Юниты, стоящие в начале хода на дороге или мосту, получают в этот ход движение +1.',  // TECH.log3.desc
  '全军视野 +1；迷雾关闭的对局中改为占领值 +10%。': 'Обзор всей армии +1; в партиях с выключенным туманом вместо этого очки захвата +10%.',  // TECH.int1.desc
