  // ── 阵营科技说明 ──
  '车辆造价 −10%。': 'Цена техники −10%.',  // TECH.red_h1.desc
  '自行火炮、火箭炮、战列舰攻击 +10%。': 'Атака САУ, РСЗО и линкоров +10%.',  // TECH.red_f1.desc
  '舰船移动力 +1。': 'Движение кораблей +1.',  // TECH.blue_n1.desc
  '舰船在港口修理免费；舰船造价 −10%。': 'Ремонт кораблей в порту бесплатный; цена кораблей −10%.',  // TECH.blue_n2.desc
  '舰船与其他己方舰船相邻时，防御 +15%、攻击 +10%。': 'Корабль на клетке, соседней с другим вашим кораблём, получает защиту +15% и атаку +10%.',  // TECH.blue_n3.desc
  '航空单位视野 +2、防御 +5%。': 'Воздушные юниты: обзор +2, защита +5%.',  // TECH.blue_a1.desc
  '航空单位移动力 +1。': 'Движение воздушных юнитов +1.',  // TECH.blue_a2.desc
  '航空单位位于己方舰船 2 格内时，攻击 +20%。': 'Воздушный юнит в пределах 2 клеток от вашего корабля получает атаку +20%.',  // TECH.blue_a3.desc
  '位于森林、废墟的己方单位防御 +10%。': 'Защита ваших юнитов в лесу и руинах +10%.',  // TECH.green_m2.desc
  '狙击手、投弹手造价 −25%、射程 +1（各项射程加成合计最多 +2）。': 'Снайперы и гренадеры: цена −25%, дальность +1 (все бонусы дальности в сумме дают не более +2).',  // TECH.green_m3.desc
