  '设有天数上限时，到期后先比较各队的收入建筑数，再比较单位总造价。': 'Если задан лимит дней, по его истечении сначала сравнивается число доходных зданий команд, затем общая цена юнитов.',  // codex.js:238
  '每座建筑有 20 点占领值，每次占领减去单位当前的 HP。满 HP 的单位需 2 回合完成占领。': 'У каждого здания 20 очков захвата, каждый захват снимает столько очков, сколько HP сейчас у юнита. Юниту с полным HP на захват нужно 2 хода.',  // codex.js:247
  '占领中的单位离开或被击毁时，占领值恢复为 20。不可占领友方的建筑。': 'Если захватывающий юнит уходит или уничтожен, очки захвата возвращаются к 20. Здания союзников захватывать нельзя.',  // codex.js:248
  '两个单位的 HP 相加，超过 10 的部分按造价返还资金。': 'HP двух юнитов складывается, а излишек сверх 10 возвращается средствами по цене юнита.',  // codex.js:250
  '受到不相邻的敌方单位攻击时不可反击。': 'Юнит не контратакует, если атаковавший вражеский юнит стоит не на соседней клетке.',  // codex.js:260
  '己方雷达塔 5 格范围内的己方单位攻击 +10%。多座雷达塔的效果不叠加。': 'Ваши юниты в пределах 5 клеток от вашего радара получают атаку +10%. Эффект нескольких радаров не складывается.',  // codex.js:276
  '迷雾开启时，己方雷达塔可看见周围 5 格。': 'Если туман включён, ваш радар видит 5 клеток вокруг себя.',  // codex.js:276
  '不提供收入。': 'Дохода не даёт.',  // codex.js:276
  '可占领建筑的兵种进入后可发射一次：指定一格为中心，2 格内所有单位各损失 3 HP。': 'Юнит, способный захватывать здания, войдя сюда, может один раз запустить ракету: указывается центральная клетка, и все юниты в пределах 2 клеток от неё теряют по 3 HP.',  // codex.js:277
  '每击毁一个敌方单位，星级 +1，最高 3 星。': 'За каждый уничтоженный вражеский юнит звёзды +1, не более 3★.',  // codex.js:278
  '每 1 星攻击 +5%、防御 +5%。': 'За 1★: атака +5%, защита +5%.',  // codex.js:278
  '运输单位移动后选择“卸载”，将搭载的单位放置到相邻且可进入的空格。卸载的单位本回合不可再行动。': 'После движения транспорта выберите «Высадка» и поставьте юнит на соседнюю свободную клетку, доступную ему. Высаженный юнит в этот ход больше не действует.',  // codex.js:282
  '技能槽积满后，可在己方回合发动技能，效果持续至己方下回合开始。': 'Когда шкала навыка заполнена, навык можно применить в свой ход; эффект длится до начала вашего следующего хода.',  // codex.js:284
  '技能仅对己方阵营生效。各指挥官的技能见“指挥官”页。': 'Навык действует только на вашу фракцию. Навыки командиров см. на странице «Командиры».',  // codex.js:284
  '特长与阵营特性': 'Таланты и черты фракций',  // codex.js:285
  '每位指挥官拥有一项特长，开局即生效。': 'У каждого командира есть один талант, он действует с начала партии.',  // codex.js:286
  '指挥官同时具有所属阵营的特性，与本局军队的颜色无关。': 'Командир также получает черту своей фракции независимо от цвета армии в этой партии.',  // codex.js:287
  '研究点来源：研究经费、己方科研所，以及各阵营的研究方式（见“阵营”页）。': 'Источники очков науки: бюджет науки, ваши лаборатории и способ исследований фракции (см. страницу «Фракции»).',  // codex.js:294
