  '电脑回合以 4 倍速播放。': 'Ход компьютера показывается в 4 раза быстрее.',  // ui-front.js:305
  '镜头跟随电脑': 'Камера за компьютером',  // ui-front.js:306
  '电脑行动时，镜头自动跟随。': 'Во время хода компьютера камера следует за ним автоматически.',  // ui-front.js:306
  '在地图上显示格线。': 'Показывать сетку на карте.',  // ui-front.js:307
  '转场动画': 'Заставки',  // ui-front.js:308
  '开战、回合切换、胜负时的阵营色横条和大字。关闭后回合切换改为普通横幅。': 'Полосы в цвете фракции и крупные надписи в начале боя, при смене хода и в конце партии. Если отключить, смену хода показывает обычный баннер.',  // ui-front.js:308
  '常显按键提示': 'Подсказки всегда',  // ui-front.js:309
  '关：仅在菜单、选择目标等场合显示按键提示。开：对局中始终显示。': 'Выкл: подсказки по кнопкам видны только в меню, при выборе цели и в подобных случаях. Вкл: видны в партии всегда.',  // ui-front.js:309
