  '{fort}上的远程单位射程 +1，两者不叠加。': 'Дальность +1: дальнобойные юниты на клетке «{fort}». Эти два бонуса не складываются.',
  '{mountain}上的步兵类远程单位射程 +1，两者不叠加。': 'Дальность +1: пехотные дальнобойные юниты на клетке «{mountain}». Эти два бонуса не складываются.',
  '车辆在{land}修理，航空单位在{airport}修理，舰船在{port}修理。步兵类单位可在任意己方建筑修理。': 'Техника ремонтируется на клетках: {land}; воздушные юниты — на клетке «{airport}»; корабли — на клетке «{port}». Пехота ремонтируется в любом вашем здании.',
  '车辆在{land}修理，航空单位在{airport}修理。步兵类单位可在任意己方建筑修理。': 'Техника ремонтируется на клетках: {land}; воздушные юниты — на клетке «{airport}». Пехота ремонтируется в любом вашем здании.',
  '车辆在{land}修理，舰船在{port}修理。步兵类单位可在任意己方建筑修理。': 'Техника ремонтируется на клетках: {land}; корабли — на клетке «{port}». Пехота ремонтируется в любом вашем здании.',
  '车辆在{land}修理。步兵类单位可在任意己方建筑修理。': 'Техника ремонтируется на клетках: {land}. Пехота ремонтируется в любом вашем здании.',
  '与{name}相邻的己方车辆、航空单位、舰船每回合恢复 1 HP（无需支付资金）。': 'Ваша техника, воздушные юниты и корабли на клетках, соседних с юнитом «{name}», восстанавливают 1 HP за ход (без оплаты).',
  '与{name}相邻的己方步兵类单位每回合恢复 2 HP（无需支付资金）。多名{name}的效果不叠加。': 'Ваша пехота на клетках, соседних с юнитом «{name}», восстанавливает 2 HP за ход (без оплаты). Эффект нескольких юнитов «{name}» не складывается.',
  '{name}可搭载 {n} 个陆上单位': '{name} перевозит наземных юнитов: {n}',
