  '击毁敌方的强化单位时，获得它强化价的一半（向上取整）。运输单位搭载的强化单位各自计算。': 'За уничтожение вражеского усиленного юнита вы получаете половину его цены усиления (с округлением вверх). Каждый усиленный юнит в транспорте учитывается отдельно.',
  '步兵类单位在{mountain}上视野 +3。己方建筑可看见所在的一格，{hq}可看见周围 2 格，{tower}可看见周围 5 格。': 'Пехота на клетке «{mountain}»: обзор +3. Ваши здания видят свою клетку, {hq} — 2 клетки вокруг, {tower} — 5 клеток вокруг.',
  '步兵类单位在{mountain}上视野 +3。己方建筑可看见所在的一格，{hq}可看见周围 2 格。': 'Пехота на клетке «{mountain}»: обзор +3. Ваши здания видят свою клетку, {hq} — 2 клетки вокруг.',
  '步兵类单位在{mountain}上视野 +3。己方建筑可看见所在的一格，{tower}可看见周围 5 格。': 'Пехота на клетке «{mountain}»: обзор +3. Ваши здания видят свою клетку, {tower} — 5 клеток вокруг.',
  '步兵类单位在{mountain}上视野 +3。己方建筑可看见所在的一格。': 'Пехота на клетке «{mountain}»: обзор +3. Ваши здания видят свою клетку.',
  '己方建筑可看见所在的一格，{hq}可看见周围 2 格，{tower}可看见周围 5 格。': 'Ваши здания видят свою клетку, {hq} — 2 клетки вокруг, {tower} — 5 клеток вокруг.',
  '己方建筑可看见所在的一格，{hq}可看见周围 2 格。': 'Ваши здания видят свою клетку, {hq} — 2 клетки вокруг.',
