  '战役：击败任意一位{name}大将': 'Кампания: победить любого генерала фракции «{name}»',
  '自由对局：用四国各在一场对局中击败电脑（已完成 {a}/{b}）': 'Свободная партия: по одной победе над компьютером за каждую из четырёх держав (выполнено {a}/{b})',
  '还需 {n} 研究点': 'Не хватает очков науки: {n}',
  '还需 {n} 点': 'Не хватает: {n} оч.',
  '再积累 {n} 研究点可解锁「{name}」': 'Ещё {n} оч. — и откроется «{name}»',
  '已占有全部闸房，停止涨水': 'Все шлюзовые посты взяты, подъём воды остановлен',
  '对其他阵营的看法': 'Взгляд на других',
  '克制的兵种': 'Силён против',
