// 说明文案去口语化（2026-11-13）
AWI18n.add('ru', {
  '黑潮阵营的重装步兵，可占领建筑。对步兵类单位和轻型车辆的伤害高于步兵，受到坦克的伤害明显低于步兵。': 'Тяжёлая пехота Чёрного Прилива. Может захватывать здания. Наносит пехоте и лёгкой технике больше урона, чем стрелок, а от танков получает заметно меньше урона, чем стрелок.',
  '黑潮阵营的重型坦克，攻击和防御都高于重型坦克。攻击后可再移动 1 格（不可再次攻击）。': 'Тяжёлый танк Чёрного Прилива: и атака, и защита выше, чем у тяжёлого танка. После атаки может пройти ещё 1 клетку (без повторной атаки).',
  '每回合提供 100 资金。停留的己方陆上单位每回合恢复 2 HP（需支付资金）。被敌方占领时，己方败北。': 'Даёт 100 средств за ход. Ваши наземные юниты, стоящие здесь, восстанавливают 2 HP за ход (за плату). Если штаб захватит противник, вы разгромлены.',
  '大闸的机房。停留的己方步兵类单位每回合恢复 2 HP（需支付资金）。在会涨水的关卡中，每占有一座闸房，下一次涨水推迟 1 天；全部占有时停止涨水。': 'Машинный зал Великого шлюза. Ваша пехота, стоящая здесь, восстанавливает 2 HP за ход (за плату). В миссиях с подъёмом воды каждый шлюзовой пост под вашим контролем откладывает следующий подъём воды на 1 день; когда под контролем все посты, подъём воды прекращается.',
  '车辆的移动力更高，步兵类单位的攻击略低。技能“闪击”：本回合全军的移动力和攻击提高。': 'Движение техники выше, атака пехоты немного ниже. Навык «Блиц»: в этот ход движение и атака всей армии повышаются.',
  '各型坦克的攻击和防御更高，其他单位的攻击较低。技能“履带洪流”：各型坦克攻击后可以再移动。': 'Атака и защита лёгких, средних и тяжёлых танков выше, атака остальных юнитов ниже. Навык «Танковая лавина»: лёгкие, средние и тяжёлые танки после атаки могут двигаться снова.',
  '远程单位的攻击更高，其中自行火炮和火箭炮提高最多。技能“炮火覆盖”：所有敌方单位损失 HP。': 'Атака дальнобойных юнитов выше, больше всего она повышена у САУ и РСЗО. Навык «Огневой вал»: все вражеские юниты теряют HP.',
  '新生产的单位当回合可以行动，所有单位造价 +10%。技能“加班”：本回合造价降低，每座生产建筑可以生产 2 次。': 'Только что произведённые юниты могут действовать в тот же ход, цена всех юнитов +10%. Навык «Аврал»: в этот ход цена юнитов снижается, каждое производственное здание может производить 2 раза.',
  '赤焰喷火兵部队的指挥官，炉前工出身，脸上有疤。嫌远距离打仗像写信吵架，喜欢凑到跟前。': 'Командир огнемётчиков Алого Пламени, бывшая горновая, на лице шрам. Говорит, что бой издалека — это ругань по переписке. Любит подойти вплотную.',
  '喷火兵和破甲兵的攻击、移动力更高，造价更低。技能“燎原”：喷火兵的攻击波及周围的敌方单位，并把森林变为荒地。': 'Атака и движение огнемётчиков и гранатомётчиков выше, цена ниже. Навык «Пожар»: атака огнемётчика задевает вражеские юниты вокруг цели и превращает лес в пустошь.',
  '己方单位被相邻的敌方单位攻击时先手反击。技能“架盾”：反击伤害 ×2，全军防御提高。': 'Ваш юнит, атакованный соседним вражеским юнитом, наносит упреждающий удар. Навык «Заслон»: урон контратак ×2, защита всей армии повышается.',
  '舰船的攻击、防御和移动力更高，造价更低。技能“怒潮”：全军恢复 HP，舰船对陆上单位的伤害提高。': 'Атака, защита и движение кораблей выше, цена ниже. Навык «Девятый вал»: вся армия восстанавливает HP, урон кораблей по наземным юнитам повышается.',
  '攻击机、轰炸机、战斗机的攻击更高，造价更低。技能“俯冲”：航空单位攻击时不受反击。': 'Атака штурмовиков, бомбардировщиков и истребителей выше, цена ниже. Навык «Пике»: при атаке воздушные юниты не получают контратаки.',
  '武装直升机的攻击和防御更高，运输直升机的搭载数更多。技能“蜂群”：直升机攻击后可以再移动。': 'Атака и защита ударных вертолётов выше, вместимость транспортных вертолётов больше. Навык «Рой»: после атаки вертолёты могут двигаться снова.',
  '潜艇的攻击更高，只有相邻时才会被发现。技能“狼群”：潜艇攻击大幅提高，攻击时不受反击。': 'Атака подлодок выше, их можно обнаружить только с соседней клетки. Навык «Волчья стая»: атака подлодок значительно повышается, при атаке они не получают контратаки.',
  '防空车、防空导弹和战斗机对航空单位的伤害更高，造价更低。技能“天网”：敌方航空单位进入射程时自动受到攻击。': 'Урон ЗСУ, ЗРК и истребителей по воздушным юнитам выше, цена ниже. Навык «Купол»: вражеские воздушные юниты, вошедшие в зону дальности, автоматически получают атаку.',
  '苍蓝舰队医院的医生。送到他手上的人，不管哪一方的，都要活着下手术台。爱管别人吃没吃饭。': 'Врач флотского госпиталя Лазурной Дали. Кто попал к нему на стол — свой или чужой, — сойдёт со стола живым. Вечно спрашивает, кто сегодня ел.',
  '己方单位每回合恢复 1 HP，在建筑上修理免费。技能“急救”：全军恢复 HP，并复活最近被击毁的一个单位。': 'Ваши юниты восстанавливают 1 HP за ход, ремонт в зданиях бесплатный. Навык «Реанимация»: вся армия восстанавливает HP, последний уничтоженный юнит возрождается.',
  '步兵类单位的攻击、占领值和视野更高。技能“全民皆兵”：己方城市出现步兵。': 'Атака, очки захвата и обзор пехоты выше. Навык «Все в строй»: в ваших городах появляются стрелки.',
  '狙击手的射程和攻击更高，移动后可以攻击。技能“一击”：狙击手、投弹手的运气取最大值，并无视目标的地形防御。': 'Дальность и атака снайперов выше, они могут атаковать после движения. Навык «В яблочко»: при атаке снайперов и гренадеров удача принимает максимальное значение, защита местности цели игнорируется.',
  '翠林负责山路和暗号的人，没人说得清她是哪个寨子的。擅长让对手先看见一点东西，再发现看错了。': 'Отвечает за горные тропы и пароли Нефритового Леса. Из какого она села, толком не знает никто. Умеет показать врагу кое-что — а потом он понимает, что видел не то.',
  '位于森林、废墟、礁石的己方单位攻击和防御更高，只有相邻时才会被发现。技能“灯火管制”：敌方单位的视野降为 1。': 'Атака и защита ваших юнитов в лесу, руинах и на рифах выше, их можно обнаружить только с соседней клетки. Навык «Светомаскировка»: обзор вражеских юнитов снижается до 1.',
  '直射单位攻击后，可以用剩余的移动力再移动。技能“风驰”：全军移动力提高，攻击时不受反击。': 'Юниты прямого огня после атаки могут двигаться снова на оставшееся движение. Навык «Вихрь»: движение всей армии повышается, при атаке ваши юниты не получают контратаки.',
  '己方单位在能进入的地形上，移动消耗都是 1。技能“寒潮”：敌方单位的移动力和视野降低。': 'Затраты движения ваших юнитов на любой доступной им местности равны 1. Навык «Стужа»: движение и обзор вражеских юнитов снижаются.',
  '己方单位的攻击不随 HP 减少而降低。技能“背水”：HP 未满的单位攻击大幅提高。': 'Атака ваших юнитов не снижается с потерей HP. Навык «Ни шагу назад»: атака юнитов с неполным HP значительно повышается.',
  '金沙七邦的司库，主管财务。只认账本，不划算的仗不打。脾气很好，从不发火，因为发火不挣钱。': 'Казначей Семи государств Золотых Песков, отвечает за финансы. Верит только счётной книге, в убыточные войны не ввязывается. Нрав ровный, не сердится никогда: злость дохода не приносит.',
  '所有单位造价 −10%，全军攻击 −10%。技能“军费”：立即获得一笔资金。': 'Цена всех юнитов −10%, атака всей армии −10%. Навык «Казна»: вы сразу получаете средства.',
  '金沙的佣兵首领，赌场少东家。谁出价高替谁打，只押赢的那边。': 'Предводитель наёмников Золотых Песков, сын хозяина игорного дома. Воюет за того, кто больше платит, а ставит только на победителя.',
  '攻击的运气范围很大，伤害的起伏也大。技能“梭哈”：运气判定三次，取最高值。': 'Разброс удачи при атаках очень велик, урон тоже сильно колеблется. Навык «Ва-банк»: удача определяется трижды, берётся наибольшее значение.',
  '占领值更高，每占领一座建筑都获得资金。技能“加征”：立即获得相当于一个回合的收入。': 'Очки захвата выше, за каждое захваченное здание вы получаете средства. Навык «Надбавка»: вы сразу получаете средства в размере дохода за один ход.',
  '己方城市也可以生产步兵类单位，步兵类单位造价更低。技能“黑市”：可以出售己方单位，返还造价的 90%。': 'Ваши города тоже могут производить пехотные юниты, цена пехоты ниже. Навык «Чёрный рынок»: можно продавать ваши юниты с возвратом 90% цены.',
  '侦察车、摩托兵的移动力和攻击更高，攻击后可以再移动。技能“穿插”：侦察车、摩托兵、运兵车可以穿过敌方单位。': 'Движение и атака разведмашин и мотоциклистов выше, после атаки они могут двигаться снова. Навык «Прорыв»: разведмашины, мотоциклисты и БТР могут проходить через вражеские юниты.',
  '位于建筑或 2 星及以上地形的单位防御更高。技能“铁壁”：全军恢复 HP，防御提高。': 'Защита юнитов в зданиях или на местности с защитой 2★ и выше повышена. Навык «Бастион»: вся армия восстанавливает HP, защита повышается.',
  '黑潮阵营的首领，六十六岁，见过三次退潮。六岁那次没了家，三十六岁那次没了妻儿。劝和、划界、分矿他都试过，每次只管三十年。说话慢，从不提高声音，说过的话一定算数。': 'Вождь Чёрного Прилива, шестьдесят шесть лет, видел три отлива. В шесть лет остался без дома, в тридцать шесть — без жены и детей. Он мирил, проводил границы, делил руду — каждый раз хватало на тридцать лет. Говорит медленно, голоса не повышает никогда. Слово держит всегда.',
  '位于荒地、废墟、陨星矿的己方单位防御更高。技能“开闸”：涨水一级，与海洋相邻的沙滩、荒地、礁石、废墟变为海洋。': 'Защита ваших юнитов на пустошах, в руинах и на метеорных рудниках выше. Навык «Шлюзы настежь»: вода поднимается на один уровень, соседние с морем пляжи, пустоши, рифы и руины становятся морем.',
  '主管海军': 'Глава флота',
  '黑潮阵营的大将，主管海军。五十八岁，老船长，四国通用的潮汐表是他年轻时编的。上一次战争，他的船队被四国轮流征用，沉得一条不剩。从那以后他只信海。像个教书先生，动手之前先讲道理。': 'Военачальник Чёрного Прилива, глава флота. Пятьдесят восемь лет, старый капитан: таблицы приливов, по которым ходят все четыре державы, он составил в молодости. В прошлую войну державы по очереди забирали его флот — и потопили до последнего судна. С тех пор он верит только морю. Похож на учителя: прежде чем ударить, объясняет.',
  '舰船的攻击和移动力更高；迷雾开启时，视野范围内礁石里的敌方单位也可见。技能“大潮”：敌方舰船的移动力大幅降低。': 'Атака и движение кораблей выше; при включённом тумане вражеские юниты на рифах в пределах вашего обзора тоже видны. Навык «Большая вода»: движение вражеских кораблей значительно снижается.',
  '主管财务': 'Глава финансов',
  '黑潮阵营的大将，主管财务，负责收买对手。四十一岁。她家三代的商行在上一次战争里赔得精光。她算过：打仗是世上最亏的买卖，每三十年亏一次，不如一次清账。客气，从不发火，说话只说一遍。': 'Военачальница Чёрного Прилива, глава финансов, отвечает за подкуп противников. Сорок один год. Торговый дом её семьи, три поколения дела, в прошлую войну разорился дотла. Она подсчитала: война — самая убыточная сделка на свете, убыток каждые тридцать лет. Лучше закрыть счёт разом. Вежлива, не сердится никогда, дважды не повторяет.',
  '所有单位造价更低，击毁敌方单位可以获得资金。技能“收购”：支付资金，买下与己方单位相邻的敌方车辆，最多 2 个。': 'Цена всех юнитов ниже, за уничтоженные вражеские юниты вы получаете средства. Навык «Скупка»: за плату покупает вражескую технику, соседнюю с вашими юнитами, не более 2 единиц.',
  '主管交通': 'Глава путей сообщения',
  '黑潮阵营的大将，主管交通，黑色装甲列车“黑潮号”的车长。三十五岁，修了半辈子路。他修的每一条路都被拿去运兵，路铺到哪，仗打到哪。他想铺完最后一条，从此世上不用再铺路。话少，力气大，认死理。': 'Военачальник Чёрного Прилива, глава путей сообщения, командир чёрного бронепоезда «Чёрный прилив». Тридцать пять лет, полжизни строил дороги. По каждой его дороге потом везли солдат: куда дошёл путь, туда пришла война. Он хочет проложить последнюю — чтобы больше на свете дорог не строили. Слов мало, силы много, упрям как столб.',
  '车辆在道路和桥梁上的防御更高；回合开始时位于道路、桥梁的车辆移动力更高。技能“封路”：敌方单位在道路和桥梁上的移动消耗增加。': 'Защита техники на дорогах и мостах выше; у техники, начавшей ход на дороге или мосту, движение выше. Навык «Шлагбаум»: затраты движения вражеских юнитов на дорогах и мостах увеличиваются.',
  '主管情报': 'Глава разведки',
  '黑潮阵营的大将，主管情报：潜伏，冒充，挑拨。二十四岁。她是在战争烧剩的寨子里被玄渊捡回来的孩子，管他叫爷爷。爱笑，说话像开玩笑，下手不开玩笑。': 'Военачальница Чёрного Прилива, глава разведки: засады, подмены, раздоры. Двадцать четыре года. Сюань Бездна подобрал её ребёнком в селе, которое сожгла война; она зовёт его дедушкой. Смешлива, говорит будто шутит. Бьёт — без шуток.',
  '位于建筑的己方步兵类单位处于隐蔽状态。技能“点灯”：让分属两个敌方阵营的相邻单位互相攻击。': 'Ваша пехота в зданиях скрыта. Навык «Ложные огни»: соседние юниты из двух разных вражеских фракций атакуют друг друга.',
  '本回合：狙击手、投弹手攻击时，运气取最大值，并无视目标的地形防御。全军攻击 +30%。': 'В этот ход: при атаке снайперов и гренадеров удача принимает максимальное значение, защита местности цели игнорируется. Атака всей армии +30%.',
  '本回合：己方攻击的运气判定三次，取最高值。全军攻击 +30%。第一次击毁敌方单位时，返还 50% 技能槽。': 'В этот ход: удача при ваших атаках определяется трижды, берётся наибольшее значение. Атака всей армии +30%. При первом уничтожении вражеского юнита возвращается 50% шкалы навыка.',
  '本回合：单位造价 −30%，每座生产建筑可生产 2 次。生产第二个单位前，要先把第一个单位移出建筑。': 'В этот ход: цена юнитов −30%, каждое производственное здание может производить 2 раза. Перед производством второго юнита первый юнит нужно вывести из здания.',
  '己方下回合开始前：敌方航空单位移动后进入己方防空车、防空导弹、战斗机的射程时，自动受到一次攻击（每个己方单位一次）。全军防御 +30%。': 'До начала вашего следующего хода: вражеский воздушный юнит, оказавшийся после движения в зоне дальности ваших ЗСУ, ЗРК или истребителей, автоматически получает одну атаку (от каждого вашего юнита — один раз). Защита всей армии +30%.',
  '立即获得相当于一个回合的收入。本回合：步兵类单位移动力 +1。': 'Вы сразу получаете средства в размере дохода за один ход. В этот ход: движение пехоты +1.',
  '打开大闸，涨水一级。与海洋相邻的沙滩、荒地、礁石、废墟变为海洋。位于这些格子的陆上单位被移到最近的空格，其中敌方单位损失 3 HP（不会被击毁）。己方下回合开始前：全军防御 +20%。每局最多涨水 2 次。不能涨水时，改为所有敌方单位各损失 1 HP（不会被击毁）。': 'Открывает Великий шлюз, вода поднимается на один уровень. Соседние с морем пляжи, пустоши, рифы и руины становятся морем. Наземные юниты на этих клетках переносятся на ближайшую свободную клетку, вражеские юниты среди них теряют по 3 HP (не могут быть уничтожены). До начала вашего следующего хода: защита всей армии +20%. Вода может подняться не более 2 раз за партию. Если поднять воду нельзя, вместо этого все вражеские юниты теряют по 1 HP (не могут быть уничтожены).',
  '买下与己方单位相邻的敌方车辆，最多 2 个，从价格高的开始买。买下的单位立即归己方所有，当回合不能行动。价格 = 造价 × 剩余 HP ÷ 10 × 50%。资金不够支付的单位不会买下。以下单位不能买：带标记的单位、搭载着单位的运输单位、位于司令部的单位、敌方阵营的最后一个单位。一个单位都没有买下时，改为获得回合收入的 50%。': 'Покупает вражескую технику, соседнюю с вашими юнитами, не более 2 единиц, начиная с самой дорогой. Купленный юнит сразу переходит к вам и в этот ход действовать не может. Цена покупки = цена юнита × оставшееся HP ÷ 10 × 50%. Юнит, на покупку которого не хватает средств, не покупается. Нельзя купить: отмеченные юниты, транспорт с юнитами на борту, юниты в штабе и последний юнит вражеской фракции. Если не куплен ни один юнит, вместо этого вы получаете 50% дохода за ход.',
  '相邻且分属不同敌方阵营的两个单位互相攻击一次，最多 2 对，每个单位只算进一对。这次攻击不会击毁单位，也不积累技能槽。没有符合条件的单位时，改为以下效果。本回合：己方攻击 +20%，攻击时不受反击。己方下回合开始前：敌方视野 −2。': 'Два соседних юнита из разных вражеских фракций один раз атакуют друг друга; не более 2 пар, каждый юнит входит только в одну пару. Эти атаки не уничтожают юниты и не заполняют шкалу навыка. Если подходящих юнитов нет, вместо этого действуют следующие эффекты. В этот ход: ваша атака +20%, при атаке ваши юниты не получают контратаки. До начала вашего следующего хода: обзор противника −2.',
  '远程：移动后不可攻击，只有不移动时才可以攻击。': 'Дальний бой: после движения атаковать не может; атаковать может, только если не двигался.',
  '一个阵营的司令部被占领，或者全部单位被击毁时，这个阵营败北。只剩一支队伍时，这支队伍获胜。': 'Фракция разгромлена, если захвачен её штаб или уничтожены все её юниты. Когда остаётся одна команда, она побеждает.',
  '受到相邻敌方单位攻击的单位如果没有被击毁，会反击，伤害按受到攻击后的 HP 计算。': 'Юнит, атакованный соседним вражеским юнитом и не уничтоженный, контратакует; урон рассчитывается по HP после атаки.',
  '远程单位移动后不可攻击，只有不移动时才可以攻击。{list}例外，移动后仍可攻击。': 'Дальнобойные юниты не могут атаковать после движения; атаковать они могут, только если не двигались. Исключение ({list}): атака после движения возможна.',
  '远程单位移动后不可攻击，只有不移动时才可以攻击。': 'Дальнобойные юниты не могут атаковать после движения; атаковать они могут, только если не двигались.',
  '没有添加内容': 'Ничего не добавлено',
  '上一局使用了这些扩展，现在没有启用，所以不能继续：{list}。存档仍然保留，重新启用这些扩展后可以继续。': 'В прошлой партии использовались эти моды, сейчас они выключены, поэтому продолжить её нельзя: {list}. Сохранение остаётся: после повторного включения этих модов партию можно продолжить.',
  'id「{a}」和文件夹名「{b}」不一致': 'id «{a}» не совпадает с именем папки «{b}»',
  '同一个 id 重复登记': 'Один и тот же id зарегистрирован повторно',
  '{a} 必须是数组': '{a} должен быть массивом',
  '{a} 必须是对象': '{a} должен быть объектом',
  '地图「{a}」的 rows / half 必须是等宽的字符串数组': 'Карта «{a}»: rows / half должен быть массивом строк одинаковой длины',
  '指挥官「{a}」的 faction 必须是 1–5': 'Командир «{a}»: faction должен быть числом 1–5',
  '指挥官「{a}」的 mods 必须是数组': 'Командир «{a}»: mods должен быть массивом',
  '指挥官「{a}」的 mods 里有无法识别的字段 {b}': 'Командир «{a}»: в mods неизвестное поле {b}',
  '指挥官「{a}」的 mods 里有无法识别的兵种类别 {b}': 'Командир «{a}»: в mods неизвестная категория юнитов {b}',
  '指挥官「{a}」的 {b} 必须是对象': 'Командир «{a}»: {b} должен быть объектом',
  '指挥官「{a}」的 fx.{b} 里有无法识别的兵种类别 {c}': 'Командир «{a}»: в fx.{b} неизвестная категория юнитов {c}',
  'balance 里有无法识别的字段 {a}': 'В balance неизвестное поле {a}',
  'mod.js 没有调用 AWMods.register（脚本出错，或者 id 不一致）': 'mod.js не вызвал AWMods.register (ошибка в скрипте или id не совпадает)',
  '扩展 id 里有不能使用的字符': 'В id мода есть недопустимые символы',
  '指挥官「{a}」的 rules 里有无法识别的效果 {b}': 'Командир «{a}»: в rules неизвестный эффект {b}',
  '指挥官「{a}」的 fx 里有无法识别的效果 {b}': 'Командир «{a}»: в fx неизвестный эффект {b}',
  '获得 S 评价的指挥官': 'Командиры с рангом S',
  '只有一名玩家对战电脑的对局才评分。': 'Оцениваются только партии одного игрока против компьютера.',
  '开局资金、建筑收入、人数补偿使用这张地图的默认设置时才评分。': 'Партия оценивается только со стандартными для этой карты стартовыми средствами, доходом зданий и форой.',
  '队伍使用这张地图的默认分法时才评分。': 'Партия оценивается только со стандартным для этой карты составом команд.',
  '这位指挥官首次获得 S 评价': 'Первый ранг S с этим командиром',
  '在困难难度获得 S 评价': 'Ранг S на сложном уровне',
  '距离 S 评价还差 {n} 分': 'До ранга S: {n} очк.',
  '完成过对局的地图': 'Карты с завершёнными партиями',
  '黑潮阵营的大将，主管海军。四国通用的潮汐表是他年轻时编的。': 'Военачальник Чёрного Прилива, глава флота. Таблицы приливов, по которым ходят все четыре державы, он составил в молодости.',
  '黑潮阵营的大将，主管情报。她是在烧剩的寨子里被玄渊捡回来的孩子，管他叫爷爷。': 'Военачальница Чёрного Прилива, глава разведки. Сюань Бездна подобрал её ребёнком в сгоревшем селе; она зовёт его дедушкой.',
  '黑潮阵营的大将，主管财务，负责收买对手。她家三代的商行在上一次战争里赔光了。': 'Военачальница Чёрного Прилива, глава финансов, отвечает за подкуп противников. Торговый дом её семьи, три поколения дела, разорился в прошлую войну.',
  '位于森林、废墟、礁石的己方单位攻击 +20%、防御 +20%，迷雾关闭时也处于隐蔽状态。位于平原、道路、桥梁、沙滩的己方单位防御 −5%。迷雾开启时全军视野 +2。己方单位移动中遇到隐蔽的敌方单位时停止移动，但行动不结束。': 'Ваши юниты в лесу, руинах и на рифах: атака +20%, защита +20%, скрыты даже при выключенном тумане. Ваши юниты на равнине, дороге, мосту и пляже: защита −5%. При включённом тумане обзор всей армии +2. Ваш юнит, встретив при движении скрытый вражеский юнит, останавливается, но его действие не заканчивается.',
  '己方攻击的运气范围变为 0 至 +40（原来 0–9）。运气超过 9 的部分按比例计入伤害：计入量 = 超出部分 × 基础伤害 ÷ 100（基础伤害超过 100 时按 100 计算）。': 'Разброс удачи ваших атак: от 0 до +40 (было 0–9). Часть удачи сверх 9 засчитывается в урон пропорционально: засчитываемое значение = превышение × базовый урон ÷ 100 (базовый урон выше 100 считается равным 100).',
  '占领值 ×1.5。每占领一座建筑，获得 150 资金；占领的是敌方建筑时，再获得 150 资金。全军攻击 −10%。': 'Очки захвата ×1.5. За каждое захваченное здание вы получаете 150 средств; если здание было вражеским, вы получаете ещё 150 средств. Атака всей армии −10%.',
  '位于建筑的己方步兵类单位处于隐蔽状态，迷雾关闭时也有效。步兵类单位攻击 +15%、占领值 ×1.5。迷雾开启时全军视野 +1。': 'Ваша пехота в зданиях скрыта, даже при выключенном тумане. Пехота: атака +15%, очки захвата ×1.5. При включённом тумане обзор всей армии +1.',
  '各型坦克防御 +15%。': 'Защита лёгких, средних и тяжёлых танков +15%.',
  '远程单位攻击时，目标的地形防御 −1 星。': 'При атаке дальнобойных юнитов защита местности цели −1★.',
  '远程单位攻击后，目标相邻四格内的敌方单位各受到本次伤害的 20%（不会被击毁；每个单位每回合因溅射最多损失 5 HP）。': 'После атаки дальнобойного юнита вражеские юниты на четырёх клетках, соседних с целью, получают по 20% нанесённого урона (не могут быть уничтожены; каждый юнит теряет от урона по площади не более 5 HP за ход).',
  '每经过 4 个己方回合，没有单位的己方城市各免费出现一个步兵，每次最多 4 个，当回合可行动。': 'Раз в 4 ваших хода в каждом вашем городе, где нет юнитов, бесплатно появляется стрелок, не более 4 за раз; они могут действовать в тот же ход.',
  '每座兵工厂每回合额外提供 1 研究点，最多 4 研究点；研究经费选“停”档时仍然有效。': 'Каждый завод даёт дополнительно 1 очко науки за ход, не более 4 очков науки; действует и при бюджете науки «Стоп».',
  '每回合额外获得 5 研究点（研究经费选“停”档时没有）。各档研究经费 +20%。': 'Каждый ход дополнительно 5 очков науки (при бюджете науки «Стоп» их нет). Бюджет науки на всех уровнях стоит +20%.',
  '每个敌方回合，第一个移动后进入己方防空导弹射程的敌方航空单位自动受到一次攻击。': 'В каждый вражеский ход первый вражеский воздушный юнит, оказавшийся после движения в зоне дальности вашего ЗРК, автоматически получает одну атаку.',
  '位于山地、沼泽的己方单位也处于隐蔽状态，规则与森林、废墟、礁石相同。': 'Ваши юниты в горах и на болоте тоже скрыты; правила те же, что для леса, руин и рифов.',
  '每回合第一次主动攻击时，运气判定两次，取较高值。': 'При первой активной атаке за ход удача определяется дважды, берётся большее значение.',
});
